import{_ as s,o as e,c as t,a5 as n}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"消息模式综述","description":"竞争消费者、发布订阅、RPC over MQ，这三个模式回答的是同一个问题，一条消息发出去之后该被谁消费。想清楚「谁消费」，消息系统的拓扑就清楚了一大半。","frontmatter":{},"headers":[],"relativePath":"scenarios/03-messaging/chapter-02-messaging-patterns.md","filePath":"scenarios/03-messaging/chapter-02-messaging-patterns.md"}'),i={name:"scenarios/03-messaging/chapter-02-messaging-patterns.md"};function r(c,a,p,l,d,g){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="消息模式综述" tabindex="-1" data-src-line="1" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">消息模式综述 <a class="header-anchor" href="#消息模式综述" aria-label="Permalink to &quot;消息模式综述&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><p data-src-line="3" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">竞争消费者、发布订阅、RPC over MQ，这三个模式回答的是同一个问题，一条消息发出去之后该被谁消费。想清楚「谁消费」，消息系统的拓扑就清楚了一大半。</p></blockquote><h2 id="competing-consumers" tabindex="-1" data-src-line="5" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">1. 竞争消费者 <a class="header-anchor" href="#competing-consumers" aria-label="Permalink to &quot;1. 竞争消费者 {#competing-consumers}&quot;">​</a></h2><p data-src-line="7" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">多个消费者监听同一个队列，每条消息只投给其中一个。它的作用是负载均衡，把处理压力摊到多台实例上。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─ Consumer 1</span></span>
<span class="line"><span>Queue ──轮询分发─────┼─ Consumer 2</span></span>
<span class="line"><span>                    └─ Consumer 3</span></span></code></pre></div><p data-src-line="15" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">分配策略默认是轮询，但真正决定「谁拿多少」的是 Prefetch。Prefetch 等于 0（默认值）时无限制预取，Broker 按轮询依次分发消息，不关心消费者是否处理完，处理快的消费者早早空闲；Prefetch 等于 1 时变成公平分发，处理完一条才推下一条，慢的少拿、快的多拿。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channel.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">basicQos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 公平分发</span></span></code></pre></div><p data-src-line="21" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">竞争消费者是消息系统最常用的模式，它的容错是天然的。一个消费者崩溃，未确认的消息重新入队，被其他消费者接手。代价是顺序不保证，同一队列的多条消息可能被不同消费者同时处理，先后就乱了。要顺序，只能降级为单个消费者，或者用消息哈希路由到固定队列，见 <a href="./chapter-06-message-ordering.html">消息顺序性</a>。</p><h2 id="_2-发布订阅-一条消息被所有订阅者处理" tabindex="-1" data-src-line="23" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">2. 发布订阅，一条消息被所有订阅者处理 <a class="header-anchor" href="#_2-发布订阅-一条消息被所有订阅者处理" aria-label="Permalink to &quot;2. 发布订阅，一条消息被所有订阅者处理&quot;">​</a></h2><p data-src-line="25" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">和竞争消费者相反，发布订阅把一条消息广播给所有订阅者。实现靠 Fanout Exchange，每个订阅者有自己的队列，消息复制到每个队列。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer ──▶ Fanout Exchange ──▶ Queue A ──▶ Consumer A</span></span>
<span class="line"><span>                              ──▶ Queue B ──▶ Consumer B</span></span></code></pre></div><p data-src-line="32" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">竞争消费者和发布订阅的区别只在一件事，一条消息被消费几次。竞争消费者只消费一次，发布订阅每个订阅者各消费一次。负载均衡用前者，事件广播用后者。</p><p data-src-line="34" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">典型场景是用户注册后要发短信、发邮件、加积分、写日志，这些动作各自独立、互不影响，一条注册事件广播出去，各订阅者各干各的。</p><h2 id="_3-rpc-over-mq-通常不该用的模式" tabindex="-1" data-src-line="36" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">3. RPC over MQ，通常不该用的模式 <a class="header-anchor" href="#_3-rpc-over-mq-通常不该用的模式" aria-label="Permalink to &quot;3. RPC over MQ，通常不该用的模式&quot;">​</a></h2><p data-src-line="38" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">RPC over MQ 用消息队列实现请求响应，客户端发请求消息，服务端处理后把结果发回回调队列，靠 correlationId 匹配请求和响应。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ──请求──▶ request.queue ──▶ Server</span></span>
<span class="line"><span>   │                                │</span></span>
<span class="line"><span>   └──响应── callback.queue ◀────────┘</span></span></code></pre></div><p data-src-line="46" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">它和 HTTP 调用的差别在于中间隔了一层 Broker，天然异步、解耦、可负载均衡，但延迟更高、复杂度更高，要自己处理 correlationId 匹配和超时。</p><p data-src-line="48" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">关键的判断是，如果只是简单的同步调用，用 HTTP 或 gRPC。RPC over MQ 只在两种情况下才值得考虑，一是已经深度依赖 RabbitMQ 且不想引入第二套调用链路，二是调用方和被调用方之间需要队列解耦。绝大多数场景下它是反模式，不要因为「消息队列能传返回值」就硬把它当 RPC 框架用。</p><h2 id="_4-怎么选" tabindex="-1" data-src-line="50" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">4. 怎么选 <a class="header-anchor" href="#_4-怎么选" aria-label="Permalink to &quot;4. 怎么选&quot;">​</a></h2><table tabindex="0"><thead data-src-line="52" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><tr data-src-line="52" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><th style="text-align:left;">需求</th><th style="text-align:left;">模式</th></tr></thead><tbody data-src-line="54" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><tr data-src-line="54" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><td style="text-align:left;">一条消息被一个消费者处理，分担负载</td><td style="text-align:left;">竞争消费者</td></tr><tr data-src-line="55" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><td style="text-align:left;">一条消息被所有订阅者各自处理</td><td style="text-align:left;">发布订阅</td></tr><tr data-src-line="56" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md"><td style="text-align:left;">同步请求响应</td><td style="text-align:left;">HTTP / gRPC，不是 MQ</td></tr></tbody></table><p data-src-line="58" data-src-file="scenarios/03-messaging/chapter-02-messaging-patterns.md">判断的根子就一条，消息的消费者是「一」还是「多」。负载均衡选竞争消费者，事件广播选发布订阅，需要请求响应用 HTTP。RPC over MQ 卡在中间，两头都不占优，大多数时候不选它。</p>`,21)])])}const m=s(i,[["render",r]]);export{h as __pageData,m as default};
